// todo.js
class Todo {
  constructor(title) {
    this.id = Date.now();
    this.title = title;
    this.completed = false;
    this.createdAt = new Date().toISOString();
    this.updatedAt = new Date().toISOString();
  }
}

module.exports = Todo;

// store.js
const todos = [];

function findById(id) {
  return todos.find((todo) => todo.id === id);
}

function getAll(filterCompleted = null) {
  if (filterCompleted !== null) {
    const filteredTodos = todos.filter((todo) => filterCompleted === todo.completed);
    return filteredTodos;
  }
  return todos;
}

function create(todo) {
  if (!todo.title || typeof todo.title !== "string" || todo.title.length < 1 || todo.title.length > 100) {
    throw new Error("Invalid title");
  }
  const createdTodo = new Todo(todo.title);
  todos.push(createdTodo);
  return createdTodo;
}

function update(id, updates) {
  const todo = findById(id);
  if (!todo) {
    throw new Error("Todo not found");
  }

  for (const key in updates) {
    todo[key] = updates[key];
  }
  todo.updatedAt = new Date().toISOString();
  return todo;
}

function remove(id) {
  const index = todos.findIndex((todo) => todo.id === id);
  if (index < 0) {
    throw new Error("Todo not found");
  }
  todos.splice(index, 1);
  return { success: true };
}

module.exports = {
  findById,
  getAll,
  create,
  update,
  remove
};

